INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '1b92ec4b-cc20-5e4c-aa10-cc1c3fbf98d7', '8e2a2ce9-ced1-5ead-a805-6d2625ee7e2a',
  'Given an array of integers.

Your task is to implement a function with the following prototype:

```cpp
bool consecutiveOnes(vector<int>& nums);
```

The function returns if all the 1s appear consecutively in `nums`.

**Note:**
- The iostream and vector libraries have been included and namespace std is being used. No other libraries are allowed.
- You can write helper functions.

**For example:**

| Test | Result |
| :--- | :--- |
| `vector<int> nums {0, 1, 1, 1, 9, 8};`<br>`cout << consecutiveOnes(nums);` | 1 |

Đáp án: ```cpp
bool consecutiveOnes(vector<int>& nums) {
    int cnt1 = 0;
    int pos1 = 0;
    int size = nums.size();
    for (int i = 0; i < size; ++i) {
        if (nums[i] == 1) ++cnt1;
    }
    for (int i = 0; i < size; ++i)
    {
        if (nums[i] == 1) {pos1 = i; break;}
    }
    for (int i = pos1; i < pos1 + cnt1; ++i)
    {
        if (nums[i] != 1) return false;
    }
    return true;
}
```', 1
);

