  'a3b16952-ebad-52fc-8584-494b67cbf320', '8e2a2ce9-ced1-5ead-a805-6d2625ee7e2a',
  'The prices of all cars of a car shop have been saved as an array called `N`. Each element of the array `N` is the price of each car in the shop.

A person, with the amount of money `k`, wants to buy as many cars as possible.

**Request:** Implement the function

```cpp
buyCar(int* nums, int length, int k);
```

Where `nums` is the array `N`, `length` is the size of this array, and `k` is the amount of money the person has. Find the maximum number of cars this person can buy with his money, and return that number.

**Example:**

`nums = [90, 30, 20, 40, 50]; k = 90;`

The result is 3; he can buy the cars having indices 1, 2, and 3 (the first index is 0).

**Note:** The libraries `iostream` and `algorithm`, and `using namespace std`, have been used. You can add other functions, but you are not allowed to add other libraries.

**For example:**

| Test | Result |
| :--- | :--- |
| `int nums[] = {90,30,40,90,20};` | 3 |
| `int length = sizeof(nums)/sizeof(nums[0]);` | |
| `cout << buyCar(nums, length, 90) << "\n";` | |', 2
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'b990ac41-91fd-5873-9843-9f8d594e0635', '8e2a2ce9-ced1-5ead-a805-6d2625ee7e2a',
  'Given an array of integers sorted in ascending order and an integer target.

Your task is to implement a function with the following prototype:

```cpp
int sumLessThanTarget(vector<int>& nums, int target);
```

The function returns the largest sum of a pair of the numbers in `nums` whose sum is less than `target`. The test cases ensure that a solution exists.

**Note:**
- The `iostream`, `vector`, and `climits` libraries have been included, and `namespace std` is being used. No other libraries are allowed.
- You can write helper functions.

**For example:**

| Test | Result |
| :--- | :--- |
| `vector<int> nums {1, 2, 3, 5, 6, 9};`<br>`int target = 7;`<br>`cout << sumLessThanTarget(nums, target);` | 6 |

**Answer:** (penalty regime: 0 %)

Đáp án: ```cpp
using vtint = vector<int>;
int sumLessThanTarget(vector<int >& nums, int target) {
    int size = nums.size();
    int maxs = 0;
    int sum = 0;
    vtint arr;
    for (int i = 0; i < size; ++i)
    {
        if (nums[i] < target) arr.push_back(nums[i]);
    }
    size = arr.size();
    for (int i = 0; i < size-1; ++i)
    {
        for (int j = i+1; j < size; ++j)
        {
            sum = arr[i] + arr[j];
            if (sum >= target) continue;
            else {if (sum > maxs) maxs = sum;}
        }
    }
    return maxs;
}
```', 3
);

